-- Schema is the single source of truth (docs/retningslinjer/database.md). It also runs against kongarthur_test.
-- Ids are GENERATED BY DEFAULT, so the seed can insert fixed ids; the seed then moves each sequence past them.

-- unaccent + pg_trgm make guest name search case- and accent-insensitive and indexable (001 FR-002, 006 FR-010)
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- unaccent() is only STABLE (its dictionary could change), and an index needs an IMMUTABLE expression.
-- Naming the dictionary pins it, which is the documented way to make the wrapper safe to index.
CREATE FUNCTION search_key(value TEXT) RETURNS TEXT
  LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
  RETURN lower(public.unaccent('public.unaccent'::regdictionary, value));

CREATE TABLE countries (
  code CHAR(2) PRIMARY KEY,
  name VARCHAR(100) NOT NULL
);

CREATE TABLE room_types (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(50) NOT NULL UNIQUE,
  capacity SMALLINT NOT NULL,
  CHECK (capacity > 0)
);

CREATE TABLE rooms (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  room_number VARCHAR(10) NOT NULL UNIQUE,
  room_type_id INT NOT NULL REFERENCES room_types (id)
);

CREATE TABLE seasons (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(50) NOT NULL UNIQUE
);

-- Periods must cover the year without overlap; the seed generator ensures it
CREATE TABLE season_periods (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  season_id INT NOT NULL REFERENCES seasons (id),
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  CHECK (end_date >= start_date)
);

CREATE TABLE room_prices (
  room_type_id INT NOT NULL REFERENCES room_types (id),
  season_id INT NOT NULL REFERENCES seasons (id),
  price_per_night NUMERIC(10, 2) NOT NULL,
  PRIMARY KEY (room_type_id, season_id),
  CHECK (price_per_night >= 0)
);

-- No room_type_id: the type is derived from rooms.room_type_id, storing it here would be a transitive dependency (3NF)
CREATE TABLE bookings (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  -- First and family name are two facts, as in the assignment's data (1NF, 004 FR-006)
  first_name VARCHAR(75) NOT NULL,
  family_name VARCHAR(75) NOT NULL,
  country_code CHAR(2) NOT NULL REFERENCES countries (code),
  room_id INT NOT NULL REFERENCES rooms (id),
  check_in DATE NOT NULL,
  check_out DATE NOT NULL,
  guest_count SMALLINT NOT NULL,
  -- Deliberate exception: the price at booking/edit time is a frozen historical fact (FR-009)
  total_price NUMERIC(10, 2) NOT NULL,
  source VARCHAR(20) NOT NULL DEFAULT 'backoffice',
  -- NULL = not registered; set at check-out (003 FR-011)
  satisfaction_score SMALLINT NULL,
  -- NULL = not registered. Only today's arrivals and departures are registered; earlier stays follow the dates (005 FR-003)
  -- TIMESTAMP(0): whole seconds in Danish local time, as the API has always returned them
  checked_in_at TIMESTAMP(0) NULL,
  checked_out_at TIMESTAMP(0) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT LOCALTIMESTAMP(0),
  CHECK (CHAR_LENGTH(TRIM(first_name)) > 0),
  CHECK (CHAR_LENGTH(TRIM(family_name)) > 0),
  CHECK (check_out > check_in),
  CHECK (guest_count > 0),
  CHECK (total_price >= 0),
  CHECK (source IN ('backoffice', 'booking_system')),
  CHECK (satisfaction_score BETWEEN 1 AND 5)
);

CREATE TABLE drink_categories (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE drinks (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(100) NOT NULL UNIQUE,
  drink_category_id INT NOT NULL REFERENCES drink_categories (id),
  price NUMERIC(10, 2) NOT NULL,
  CHECK (price >= 0)
);

CREATE TABLE bar_sales (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  drink_id INT NOT NULL REFERENCES drinks (id),
  quantity SMALLINT NOT NULL,
  -- Deliberate exception: the drink's price at the time of sale is a frozen historical fact (FR-010)
  unit_price NUMERIC(10, 2) NOT NULL,
  sold_at TIMESTAMP(0) NOT NULL DEFAULT LOCALTIMESTAMP(0),
  -- The sale is kept when the booking is deleted (FR-010a)
  booking_id INT NULL REFERENCES bookings (id) ON DELETE SET NULL,
  CHECK (quantity >= 1),
  CHECK (unit_price >= 0)
);

CREATE TABLE users (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username VARCHAR(50) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL
);

-- PostgreSQL does not index foreign keys by itself (006 FR-010). The small tables (rooms, seasons, room_prices,
-- drinks …) fit in a page or two, where EXPLAIN always picks a scan over an index, so only the keys on bookings and
-- bar_sales get an index.
CREATE INDEX ON bookings (room_id, check_in, check_out);
CREATE INDEX ON bookings (check_in);
CREATE INDEX ON bookings (country_code);
-- '%…%' search cannot use a B-tree; a trigram index can, for search terms of three letters or more
CREATE INDEX ON bookings USING gin (search_key(first_name || ' ' || family_name) gin_trgm_ops);
CREATE INDEX ON bar_sales (sold_at);
CREATE INDEX ON bar_sales (drink_id);
-- Without it, deleting a booking reads every bar sale to apply ON DELETE SET NULL (FR-010a)
CREATE INDEX ON bar_sales (booking_id);
